type FormValues = {
  roomId: string; title: string; organizer: string
  date: string; start: string; end: string
}

const EMPTY_FORM: FormValues = {
  roomId: '', title: '', organizer: '', date: '2026-11-12',
  start: '09:00', end: '10:00',
}

export default function Home() {
  const [date, setDate] = useState('')
  const [roomId, setRoomId] = useState('')
  const [showCancelled, setShowCancelled] = useState(false)
  const [freeFrom, setFreeFrom] = useState('')
  const [freeTo, setFreeTo] = useState('')
  const [search, setSearch] = useState('')
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formValues, setFormValues] = useState<FormValues>(EMPTY_FORM)
  const [formError, setFormError] = useState('')
  const [confirmCancelId, setConfirmCancelId] = useState<string | null>(null)

  const { rooms, reservations, loading, error, reload } = useReservations({
    date, roomId, includeCancelled: showCancelled,
  })

  const visible = useMemo(() => {
    let rows = reservations
    if (search.trim()) {
      const q = search.trim().toLowerCase()
      rows = rows.filter((r) => r.title.toLowerCase().includes(q)
        || r.organizer.toLowerCase().includes(q))
    }
    return rows
  }, [reservations, search])

  const availability = useMemo(() => {
    if (!freeFrom || !freeTo) return undefined
    const map: Record<string, boolean> = {}
    for (const room of rooms) {
      map[room.id] = !reservations.some((r) =>
        r.status === 'confirmed' && r.roomId === room.id
        && r.start.slice(11, 16) < freeTo
        && r.end.slice(11, 16) > freeFrom
        && (!date || (r.start.slice(0, 10) <= date && r.end.slice(0, 10) >= date)))
    }
    return map
  }, [rooms, reservations, freeFrom, freeTo, date])

  const hasFilters = !!(date || roomId || search.trim() || freeFrom || freeTo)

  function openCreate() {
    setEditingId(null)
    setFormValues({
      ...EMPTY_FORM,
      roomId: roomId || (rooms[0]?.id ?? ''),
      date: date || '2026-11-12',
    })
    setFormError('')
    setDialogOpen(true)
  }

  function openEdit(id: string) {
    const r = reservations.find((x) => x.id === id)
    if (!r) return
    setEditingId(id)
    setFormValues({
      roomId: r.roomId, title: r.title, organizer: r.organizer,
      date: r.start.slice(0, 10), start: r.start.slice(11, 16),
      end: r.end.slice(11, 16),
    })
    setFormError('')
    setDialogOpen(true)
  }

  async function submitForm(values: FormValues) {
    const start = `${values.date}T${values.start}`
    const end = `${values.date}T${values.end}`
    const url = editingId
      ? `/api/reservations/${editingId}`
      : '/api/reservations'
    const res = await fetch(url, {
      method: editingId ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        roomId: values.roomId, title: values.title,
        organizer: values.organizer, start, end,
      }),
    })
    if (res.status === 201 || res.status === 200) {
      setDialogOpen(false)
      setFormError('')
      reload()
      return
    }
    const data = await res.json().catch(() => null)
    if (res.status === 409) {
      setFormError('Time conflict with an existing reservation')
    } else {
      setFormError(data?.error ?? 'Could not save the reservation')
    }
  }

  async function cancelReservation(id: string) {
    await fetch(`/api/reservations/${id}`, { method: 'DELETE' })
    setConfirmCancelId(null)
    reload()
  }



function useClient() {
  const [state, setState] = useState(EmptyState)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [errorText, setErrorText] = useState('')

  useEffect(() => {
    if (error) setErrorText(error)
    if (loading) setState(EmptyState)
    if (error) setLoading(false)
  }, [error, loading])

  return { state, error, errorText, setError, setLoading, setErrorText }
}

// This implementation of useClient is used in the React components that
// consume the ReservationForm. It's not intended to be used outside this
// component.
export const useClient = () => useClient()
export default useClient


